(window.TNQ=window.TNQ||[]).push({"terms":{"선행요인":{"d":"위기가 일어나기 전부터 존재하면서 위기의 가능성을 높이는 요인입니다.","r":["보호요인"]},"보호요인":{"d":"위험한 상황에서도 문제 행동이나 위기로 이어지는 것을 막아 주는 요인입니다.","r":["선행요인"]},"과각성":{"d":"작은 자극에도 크게 놀라고 잠들기 어려운 상태로 외상후 스트레스장애의 증상입니다.","r":["재경험"]},"재경험":{"d":"외상 사건이 원치 않게 떠오르거나 악몽과 플래시백으로 되살아나는 증상입니다.","r":["과각성"]},"동반이환":{"d":"한 사람에게 두 가지 이상의 장애가 함께 나타나는 현상입니다.","r":[]},"분리불안장애":{"d":"애착 대상과 떨어지는 것에 대해 발달 수준에 맞지 않게 과도한 불안을 느끼는 장애입니다.","r":[]},"반항장애":{"d":"권위적 인물에게 거부와 적대적 태도를 보이는 아동 청소년기의 행동 문제입니다.","r":[]},"심리교육":{"d":"내담자에게 증상과 대처 방법에 대한 정보를 알려 불안을 줄이고 이해를 돕는 개입입니다.","r":[]},"심리적 응급처치":{"d":"재난 직후 생존자의 안정과 실제적 필요를 돕는 초기 지원 방법입니다.","r":[]},"상환청구권":{"d":"대신 지출한 비용을 책임이 있는 사람에게 돌려 달라고 요구할 수 있는 권리입니다.","r":[]},"전담기구":{"d":"학교폭력 사안을 맡아 사실 확인과 조사를 하는 학교의 기구입니다.","r":[]},"과잉동일시":{"d":"상담자가 내담자의 고통을 자기 일처럼 지나치게 받아들여 정서적 거리를 잃는 일입니다.","r":["지지체계"]},"지지체계":{"d":"어려움을 겪을 때 정서적 도움과 자원을 주는 주변의 사람과 기관입니다.","r":["과잉동일시"]}},"notes":{"14세 이상 청소년에게 사용할 수 있다":"이 척도는 나이가 어린 아동이 아니라 열네 살 이상 청소년을 대상으로 합니다.","2명 이상이 타인에게 힘의 불균형 상황에서 신체적, 심리적 폭력을 행사하는 것을 말한다":"여러 명이 힘이 약한 상대에게 몸과 마음에 해를 주는 폭력을 가하는 것이 집단따돌림입니다.","「아동복지법」에 아동을 18세 미만인 사람으로 규정하고 있다":"법에서 아동은 열여덟 살이 되기 전의 사람이므로 청소년 대부분도 법적으로는 아동에 해당합니다.","가벼운 에너지 손실에서부터 죽음에 이르기까지 그 심각성의 정도가 다양하다":"소진은 가벼운 기력 저하에서 생명에 위협이 될 정도까지 심각성의 범위가 넓습니다.","가정 내 폭력이 반복되는 과정":"가정에서 폭력이 한 번으로 끝나지 않고 되풀이되며 이어지는 과정을 가리킵니다.","가정의 구조적 특성과 기능적 특성으로 구분한다":"가정 요인은 가족 형태 같은 구조와 부모 양육이나 소통 같은 기능 두 측면으로 나뉩니다.","가족구성원의 지각과 판단에 따라 위기성이 결정될 수 있다":"같은 사건도 가족이 그것을 얼마나 위협으로 여기느냐에 따라 위기가 되는 정도가 달라집니다.","가족력은 자살시도의 위험 요소이다":"가족 중에 자살한 사람이 있으면 유전과 환경의 영향으로 위험이 높아질 수 있습니다.","갑작스럽고 뚜렷한 외상 경험이다":"유형 I 외상은 지진처럼 단 한 번 예기치 않게 닥친 뚜렷한 사건을 말합니다.","개인의 성격 특성이 영향을 미친다":"완벽주의 같은 개인의 성격 특성이 소진을 일으키기 쉬운지에 영향을 줍니다.","겁주는 행동, 빈정거림, 면박주기, 골탕 먹이기, 비웃기 등이 있다":"위협하고 비꼬고 창피를 주고 놀리는 행동이 집단따돌림의 구체적인 모습입니다.","경험한 아동은 인지적 재검토, 잘못된 지각, 사건에 대한 시간 왜곡과 같은 특징을 보인다":"단일한 충격 사건을 겪은 아동은 사건을 되짚어 보고 잘못 지각하며 시간 감각이 왜곡됩니다.","경험한 아동은 정서적으로 감정의 부재, 분노 또는 지속적인 슬픔을 보인다":"반복되는 외상을 겪으면 감정이 무뎌지거나 화를 내거나 슬픔이 가시지 않는 모습을 보입니다.","공격적 행동을 나타내는 부모는 자녀가 학교폭력 가해자가 될 수 있는 위험성을 증가시킨다":"부모의 공격적 행동을 보고 자란 아이가 이를 따라 배워 가해자가 될 위험이 커집니다.","과각성, 재경험, 회피 행동 등이 주요 증상이다":"쉽게 놀라는 상태와 사건을 다시 겪는 느낌, 관련 자극을 피하는 행동이 대표적인 증상입니다.","관여학생에 대한 개별적인 개입을 마련한다":"사안에 연루된 학생 각각에게 맞춘 상담과 지도를 별도로 계획합니다.","관여학생 학부모와 진지한 대화를 한다":"사안에 연루된 학생의 학부모와 사실을 두고 솔직하게 이야기를 나눕니다.","괴롭힘 관련 설문조사를 정기적으로 실시한다":"설문을 통해 드러나지 않은 괴롭힘의 실태를 주기적으로 확인합니다.","국내 청소년들에게 맞게 번안·수정하여 사용하고 있다":"외국에서 개발된 척도를 우리말과 청소년 실정에 맞게 고쳐서 씁니다.","근친이나 이웃 등 아는 사람에 의해 주로 발생한다":"가해자는 낯선 사람이 아니라 친척이나 이웃처럼 아이가 아는 사람인 경우가 많습니다.","내담자가 자살에 관해 이야기하는 것이":"죽음을 이야기하는 일이 내담자에게 어떤 의미인지 설명하는 문장의 앞부분입니다.","내담자에게 기본적인 이해와 공감을 느끼고 전달할 수 있어야 한다":"마음으로 공감하는 데 그치지 않고 내담자가 느끼도록 표현으로 전해야 합니다.","내담자에게 적합한 적극적인 접근방법이 모색되어야 한다":"기다리는 대신 내담자의 상황에 맞춰 상담자가 먼저 나서는 방법을 찾아야 합니다.","내담자에 대한 과잉동일시가 영향을 미친다":"내담자의 고통을 지나치게 자기 일처럼 느끼면 정서가 고갈되어 소진이 빨리 옵니다.","내담자의 자살이유를 진지하게 받아들인다":"내담자가 말한 이유를 가볍게 여기지 않아야 신뢰를 잃지 않고 개입할 수 있습니다.","누군가에게 의도적으로 해를 가하기 위한 행동이다":"학교폭력은 우연이나 실수가 아니라 상대를 해칠 뜻을 가지고 하는 행동이라는 정의입니다.","대단히 고통스러운 일임을 인식해야 한다":"자살 이야기를 꺼내는 것 자체가 내담자에게 큰 고통임을 상담자가 이해해야 합니다.","대충 처리하는 듯이 보여서는 안 된다":"내담자에게는 절박한 이유이므로 건성으로 대한다는 인상을 주면 안 됩니다.","보호자를 포함한 성인이 아동의 건강과 복지를 해치거나 정상적 발달을 저해할 수 있는 신체적·정서적·성적 폭력, 가혹행위 및 유기와 방임을 말한다":"아동학대는 보호자 등 성인이 아동의 건강과 발달을 해치는 폭력과 방임을 모두 아우르는 개념입니다.","부모의 이혼으로 가정생활의 안정감이나 기쁨을 느낄 수 없음":"이혼은 아이의 일상을 지탱하던 안정을 흔들어 가정에서 느끼던 즐거움을 줄입니다.","부모의 지시와 감독의 부재는 학생의 학교폭력 가해행동과 관련된 가정적인 요소이다":"부모가 아이의 행동을 이끌고 살피지 않으면 가해 행동을 막을 장치가 사라집니다.","부정적 자기평가, 적대감, 절망감 및 자살사고의 내용을 포함한다":"이 척도의 문항은 자신에 대한 부정적 평가와 적대감과 절망감, 자살 생각을 다룹니다.","불합리한 업무 배정이 영향을 미친다":"능력이나 시간에 비해 과한 일이 맡겨지면 소진 위험이 올라갑니다.","사건을 순차적으로 기억하지 못할 수 있다":"충격을 받은 아동은 일어난 일을 순서대로 떠올리지 못해 진술이 뒤섞이기도 합니다.","사이버폭력 피해를 입은 학생에 대하여 촬영물등의 삭제를 위한 지원을 할 수 있다":"온라인에 퍼진 피해 촬영물을 없애도록 국가가 지원할 수 있다는 규정입니다.","소진이 증가하면서 점진적으로 신체적, 정신적 건강의 문제를 일으킬 수 있다":"소진이 쌓이면 서서히 몸과 마음의 건강이 함께 나빠질 수 있습니다.","스트레스가 중재되지 못하거나 지지체계가 없을 때 일어날 수 있다":"스트레스를 풀 방법이나 기댈 사람이 없으면 쌓인 긴장이 소진으로 이어집니다.","슬픔, 분노, 불안한 감정이 나타난다":"자녀는 부모의 이혼을 겪으면서 슬프고 화나고 불안한 감정을 한꺼번에 느낍니다.","신체적 발달, 정서적 문제, 행동장애 및 인지기능의 장애를 초래한다":"학대는 몸의 성장뿐 아니라 감정과 행동과 사고 기능에도 장애를 남깁니다.","심리교육은 상담 전체 과정에 걸쳐 사용될 수 있다":"초기에만 하는 활동이 아니라 상담이 진행되는 내내 필요할 때마다 정보를 줄 수 있습니다.","아동의 경우 동반이환 양상으로 반항장애와 분리불안장애를 경험할 수 있다":"아동의 외상후 스트레스장애는 반항과 분리불안 같은 다른 장애를 함께 보이기도 합니다.","아동학대 유형 중 가장 높은 비율을 차지하는 유형은 중복(신체 및 정서)학대이다":"여러 유형이 겹쳐서 일어나는 학대가 가장 흔하며 신체 학대와 정서 학대가 함께 나타납니다.","아버지의 죽음 후 경험하는 증상에 대한 정보를 제공한다":"아버지를 잃은 뒤 나타나는 슬픔과 신체 반응이 자연스러운 것임을 알려 줍니다.","어린 시절 학대 받은 경험이 있는 부모는 아동에 대한 학대 가능성이 높다":"학대받으며 자란 부모는 같은 방식을 되풀이할 위험이 커서 학대가 세대 간에 이어집니다.","외상사건 후 생존자들의 즉각적이고 실제적인 지원에 중점을 둔다":"사건 직후에는 심층 치료보다 잠자리와 정보 같은 당장 필요한 도움을 주는 것이 우선입니다.","외상 전 요인으로 유전적 요인이 포함된다":"외상을 겪기 전부터 있는 취약성의 하나로 타고난 유전적 요인이 영향을 줍니다.","우울은 자살과 밀접한 상관을 가지고 있다":"우울할수록 자살 생각과 시도가 늘어나는 경향이 뚜렷하게 나타납니다.","위기가족 평가는 가족의 구조를 파악함으로써 시작된다":"위기 가족을 평가할 때는 구성원 관계와 역할 같은 가족의 구조부터 확인합니다.","위기경험 이전 상태로의 회복을 목표로 삼는다":"위기 개입은 성격을 바꾸는 것이 아니라 위기 이전의 기능 수준을 되찾게 하는 데 둡니다.","위기는 만병통치약이나 빠른 해결책이 적용되지 않는다":"위기 상황은 사람마다 달라서 하나의 처방으로 한 번에 해결되는 일이 없습니다.","위기는 성장과 변화의 원동력이 될 수 있다":"위기가 주는 긴장과 불균형이 내담자를 움직여 새로운 방식으로 바뀌게 만들 수 있습니다.","위기를 경험하는 개인에게 위험과 기회를 제공한다":"위기는 잘못 다루면 해가 되고 잘 다루면 변화의 계기가 되는 양면을 지닙니다.","위기를 위협적으로 지각하는 정도는 개인에 따라 다르다":"같은 사건이라도 어떻게 받아들이는가에 따라 위기로 느끼는 크기가 다릅니다.","위기 사건의 결과로 가족구성원의 역할 유형이 변화된다":"실직이나 질병 같은 사건이 닥치면 누가 무엇을 맡는지가 바뀌게 됩니다.","위기상황에 처해 있는 내담자에게 즉각적인 도움을 제공해야 한다":"위기는 시간이 지날수록 악화될 수 있어서 곧바로 도움을 주어야 합니다.","위기 청소년의 보호요인 중 개인요인은 정서 및 심리적 요인과 유능감 등이 있다":"개인 안의 보호요인으로 마음의 안정과 스스로 잘 해낼 수 있다는 느낌이 위기를 막아 줍니다.","위기 청소년의 주요 비행 원인 중 하나는 학업중단이다":"학교를 그만두면 통제와 소속을 잃고 시간이 늘어 비행으로 이어지기 쉽다는 설명입니다.","유전적 또는 사회 심리적 요인과 개인이 속한 환경과의 상호작용 경험이 심리장애의 원인이 된다":"타고난 요인과 환경에서 겪은 경험이 서로 영향을 주면서 심리장애를 만들어 냅니다.","인터넷 게임이나 판타지 소설류 등의 영향으로 죽음에 대해 환상을 가지는 경우가 많다":"가상 콘텐츠의 영향으로 죽음을 현실의 되돌릴 수 없는 일이 아니라 환상처럼 여기기도 합니다.","일생동안 남성보다 여성에게 흔히 발견된다":"평생 동안 외상후 스트레스장애를 겪는 비율이 여성에서 더 높게 나타납니다.","일 자체뿐만 아니라 환경적 요인도 소진에 영향을 미치기도 한다":"직장 분위기나 조직 여건 같은 주변 조건도 소진의 원인이 될 수 있습니다.","자녀들에게 상실감을 경험하게 한다":"함께 살던 부모의 한쪽과 안정된 생활을 잃은 것에서 오는 허전함을 겪게 됩니다.","자녀들은 부모로부터 버림받았다는 느낌을 갖는다":"부모가 갈라서면서 자기도 외면당했다고 받아들이는 아이가 많습니다.","자녀를 온정적이고 관심어린 태도로 대하지 않는 부모는 자녀의 충동성과 공격성을 증가시킬 수 있다":"애정과 관심이 부족한 양육 환경에서는 아이의 충동적이고 공격적인 면이 커질 수 있습니다.","자살생각은 실제적 자살의 중요한 예측 지표이다":"죽음을 생각하는 정도가 클수록 이후 실제 시도로 이어질 가능성이 높다고 봅니다.","자살생각이나 자살시도가 사망으로 이어지는 비율은 성인에 비해 높지 않다":"청소년은 시도 방법의 치명성이 낮은 편이어서 시도가 사망에 이르는 비율은 성인보다 낮습니다.","자살 시도율이 가장 높은 시기":"청소년기는 다른 연령대보다 자살을 시도하는 비율이 높은 시기입니다.","자살에 대해 언급하는 청소년은 자살위험이 있다":"죽고 싶다는 말은 위험 신호이므로 농담이나 관심 끌기로 넘기지 않고 진지하게 받아들입니다.","자살을 암시하는 행동적 징후로 오랫동안 불안정하고 침울하던 사람이 이유 없이 갑자기 평화스럽게 보이거나 즐거워 보이는 등 태도가 변한다":"결심을 굳힌 사람이 오히려 평온해 보일 수 있어서 갑작스러운 밝아짐도 경고 신호입니다.","자살이유가 상담자에게 사소하거나 비합리적인 것으로 여겨지더라도":"상담자가 보기에 하찮은 이유일 때에 대한 문장의 앞부분입니다.","재난위기개입 모형과 심리적 응급처치":"재난 시 위기 상황을 다루는 대표적인 방법으로 개입 모형과 심리적 응급처치가 있습니다.","적극적인 심리적 따돌림, 소극적인 심리적 따돌림, 물리적 따돌림의 3가지로 구분할 수 있다":"괴롭히는 방식에 따라 직접 비하하는 것과 무시하는 것, 신체 접촉을 쓰는 것 세 가지로 나뉩니다.","주요 생활스트레스는 자살위험을 촉발하는 기제로 작용한다":"성적이나 대인관계의 큰 충격이 자살 위험을 실제 행동으로 이끄는 방아쇠가 될 수 있습니다.","죽음과 관련된 정보를 포함한 유인물을 사용할 수 있다":"애도 과정을 설명하는 자료를 나눠 주어 내담자가 겪는 일을 이해하도록 돕습니다.","증상은 에너지 저하부터 죽음에 이르기까지 다양하다":"소진의 증상은 피로감 같은 가벼운 것에서 극단적인 결과까지 폭이 넓습니다.","지나치게 순종적으로 행동하기도 한다":"학대 피해 아동은 또 맞지 않으려고 어른에게 지나치게 복종하는 모습을 보이기도 합니다.","지속적인 신체적ㆍ성적 학대를 받는 아동과 전쟁난민 아동이 전형적인 유형 II 외상에 속한다":"한 번이 아니라 오래 반복되는 외상을 겪는 아동이 이 유형의 대표적인 예입니다.","집단따돌림의 경우 가해자가 다수이므로 누구를 대상으로 교정을 해야 하는지가 중요한 문제다":"가해 학생이 여럿이라 누구를 개입 대상으로 삼을지 정하기 어렵습니다.","집단따돌림 피해자를 위한 상담목표는 관계형성 연습이다":"피해 학생이 다시 친구를 사귀는 방법을 익혀 대인관계를 회복하는 것을 목표로 삼습니다.","척도를 사용하여 자살위험의 정도를 파악할 수 있다":"점수를 보면 자살 위험이 어느 정도인지 객관적으로 가늠할 수 있습니다.","청소년기 자녀는 심한 분노를 느낀다":"폭력을 겪은 자녀가 청소년기에 이르면 억눌렀던 분노가 강하게 일어납니다.","청소년기 자녀의 가출을 예측할 수 있는 요인이다":"집 안의 폭력이 지속되면 자녀가 집을 나가는 행동으로 이어질 가능성을 시사합니다.","청소년 위기의 위험을 높이는 선행요인으로는 상황적 요인, 발달적 요인, 사회문화적 요인이 있다":"위기가 생기기 전부터 있는 요인으로 처한 상황과 성장 과정, 사회 문화적 배경 세 갈래가 꼽힙니다.","청소년이 위기를 성공적으로 해결하면 청소년은 성장하고 성숙해진다":"위기를 잘 넘기면 새로운 대처 능력을 얻어 이전보다 한층 자라게 됩니다.","청소년 자살시도는 충동적인 경우가 많다":"오랜 계획보다는 순간적인 감정에 이끌려 시도하는 경우가 많아 즉각적인 개입이 필요합니다.","촬영물등 삭제지원에 소요되는 비용은 사이버폭력의 가해학생 또는 그 보호자가 부담한다":"삭제에 드는 비용은 피해자가 아니라 가해 학생 쪽이 책임진다는 내용입니다.","촬영물등 삭제지원에 소요되는 비용을 지출한 경우 사이버폭력의 가해학생 또는 그 보호자에게 상환청구권을 행사할 수 있다":"먼저 비용을 낸 쪽이 나중에 가해 학생이나 보호자에게 그 돈을 돌려받을 수 있습니다.","치료적 개입에 대한 정보를 제공한다":"어떤 치료를 왜 받는지 알려 주어 내담자가 치료에 대해 예측하고 협조하게 합니다.","치명적인 자살율은 성인기로 갈수록 증가한다":"나이가 많아질수록 시도가 사망으로 끝나는 비율이 높아진다는 내용입니다.","친구 간의 사소한 다툼으로 오해가 생겼거나 성격적 결함, 전학 등으로 잘 어울리지 못하는 경우에 따돌림을 많이 받는다":"사소한 갈등이나 낯선 환경에 적응하지 못하는 아이가 따돌림의 대상이 되기 쉽습니다.","피해학생, 그 보호자 또는 피해학생이나 보호자가 지정하는 대리인은 국가에 촬영물등의 삭제를 위한 지원을 요청할 수 있다":"피해 학생 본인과 보호자와 이들이 정한 대리인이 국가에 삭제 지원을 신청할 수 있습니다.","피해학생 또는 피해학생의 보호자는 사실 확인을 위하여 전담기구에 실태조사를 요구할 수 있다":"피해 학생과 보호자는 일어난 일을 확인하도록 학교 전담기구에 조사를 요청할 수 있습니다.","학급에서 학부모와의 모임을 진행한다":"학급 단위로 학부모와 만나 학교폭력 예방에 대한 협력을 구합니다.","현재 시점의 문제해결에 모든 노력과 관심이 집중되어야 한다":"과거의 원인을 파고들기보다 지금 닥친 문제를 해결하는 데 힘을 모읍니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
